export type DocsSection = { id: string; title: string; paragraphs: string[]; steps?: string[]; bullets?: string[]; note?: string; code?: { label: string; language: string; value: string }; links?: { label: string; href: string }[] };
export type DocsArticle = { slug: string; group: string; title: string; description: string; minutes: number; tags: string[]; sections: DocsSection[] };
export const docsGroups = ['Start here','Create your product','Pages & selling','Grow your audience','Customers & results','Account & integrations'] as const;
export const docsArticles: DocsArticle[] = [
 {slug:'getting-started',group:'Start here',title:'Your first useful product',description:'Go from an idea to a private draft, then review what your audience will see.',minutes:5,tags:['quickstart','launch','beginner'],sections:[
  {id:'start-with-expertise',title:'Start with what you can teach',paragraphs:['FiveGen brings your product content, sales page, marketing and customer work into one workspace. You supply the expertise, recordings and claims. AI assistance is optional: a manual product does not need generated course content.','Start with one audience, one useful outcome and one small piece of content. You can improve the offer after your first draft instead of filling every advanced setting upfront.']},
  {id:'make-a-draft',title:'Create a private draft',paragraphs:[],steps:['Choose Create a product, then select the format that matches what a buyer receives.','Choose the manual path, upload existing content, or use AI planning if it is available to your account.','For a course, begin in Curriculum with Upload recording, Write a lesson or Add a resource. Start with one useful lesson; complete the product name, audience and outcome in Product details as you develop it.','For other formats, add the original file, service instructions or community welcome the customer needs. Save and review the draft.']},
  {id:'review-the-experience',title:'Review three connected experiences',paragraphs:['Content is what the customer receives. Sales page is the public invitation. Price & access controls commercial terms and availability. A beautiful public page does not by itself make checkout available.'],bullets:['Use View as member to inspect the customer experience. Owner preview is a simulation and grants no purchase or access.','Use the sales-page preview to check desktop and phone layouts.','Open Launch review for required content, editorial approval and delivery publication. Use Price & access for price, payments, available sessions and the explicit selling switch. Blockers have actions that open their repair destination.'],note:'Saving a draft is private. Publication and selling are separate actions with their own review steps.'},
  {id:'next-step',title:'Make one improvement at a time',paragraphs:['If the product is useful, polish its sales page. If the promise is unclear, start with Offer research and the shared growth brief. If you already have an audience, create a lead page or campaign around the same offer. You do not need to use every marketing tool to launch.'],links:[{label:'Choose a product format',href:'/docs/create/choose-a-format'},{label:'Review your launch',href:'/docs/sell/launch-review'}]}
 ]},
 {slug:'workspace',group:'Start here',title:'Find your way around',description:'Know which workspace owns each task and how to switch products.',minutes:4,tags:['navigation','overview','save','search'],sections:[
  {id:'account-and-product',title:'Account work and product work',paragraphs:['Dashboard summarizes the business. Products is your searchable library. Customers brings relationships together. Calendar organizes private content plans and shows dated activity from its original tools. Creator Library holds private source material you choose to use.','Inside a selected product, Overview explains the next launch action. Content, Sales page, Price & access, Marketing, Customers and Settings each have a different job. Launch review is a separate content-approval destination, available from the editor or product tools; it is not the Overview dashboard or the payment form. Select the product first so edits apply to the intended offer.'],links:[{label:'Plan work in Calendar',href:'/docs/workspace/calendar'}]},
  {id:'switch-and-search',title:'Switch products confidently',paragraphs:['Use the product selector or the product rail to change context. Product icons and names help distinguish similar drafts; the library is the best place to search or filter a larger collection.','The workspace search opens destinations and products. Check the selected product name before editing a page, preparing a campaign or viewing customer records. Gen opens from the workspace header so its launcher stays clear of editor controls; open assistance when you need it, then return to the current task.']},
  {id:'save-state',title:'Understand save state',paragraphs:['Wait for Saved or Draft saved before leaving. Unsaved changes means your current edits have not reached the server. A failed save keeps the current editor open and gives a retry or recovery route.','Some child panels have their own explicit save action, including reviewed creator context. Read the panel’s save state rather than assuming that saving the product saves every external setting.'],note:'A page draft and its published version can differ. Draft saved does not mean your audience can see the edit.'},
  {id:'account-controls',title:'Account controls and help',paragraphs:['The account menu contains account destinations and Sign out. Creator plan billing, seller payment setup and customer purchases are separate areas. If you are trying to manage an offer you bought, use Your purchases rather than the creator selling settings.'],links:[{label:'Account billing and credits',href:'/docs/account/billing-and-credits'},{label:'Recover an interrupted edit',href:'/docs/help/recovery'}]}
 ]},
 {slug:'workspace/calendar',group:'Start here',title:'Plan content in Calendar',description:'Organize private schedules across products and distinguish plans from actual sends and bookings.',minutes:6,tags:['calendar','schedule','agenda','month','accounts','timezone','publishing','reminders'],sections:[
  {id:'open-calendar',title:'See dated work across your workspace',paragraphs:['Open Calendar in the global workspace navigation or search. It belongs to your account rather than one product. Month view helps compare dates; Agenda lists the current month in time order. Use Today and the previous or next controls to move through the period, then filter the account, product or campaign when you want a narrower view. Campaigns opens this same Calendar with its campaign and product selected; there is no separate campaign calendar to maintain.','The calendar combines private manual plans with dated records imported from Campaigns, Emails, service bookings and current published community events. Empty days mean no matching saved items were found; they do not prove that you published nothing outside FiveGen. Imported sources may have their own limits, so check the original tool before treating the calendar as a complete delivery ledger.']},
  {id:'planning-accounts',title:'Add a planning profile for each account',paragraphs:['A calendar account is a manually managed planning profile. Give it the platform, handle or name, a recognizable color and its time zone. These details help distinguish content you intend for different audiences or channels.','Adding an Instagram, TikTok, YouTube or other profile here does not sign in to that platform, authorize OAuth, fetch social analytics or enable publishing. Review the actual platform account and destination before you publish. A profile and follower count do not verify link eligibility or forecast reach.']},
  {id:'create-and-time',title:'Save a private plan with an explicit date',paragraphs:['Create a manual calendar item or schedule a reviewed idea from Funnel Builder. Choose the account, product when relevant, date and time. Read the displayed time zone before saving, particularly when your planning profile and current device use different zones. Switching the display zone changes how the same timed event is shown; it is not a reschedule.','Use all-day for date-based work rather than inventing a midnight appointment. All-day spans use local calendar dates with an exclusive end: an item for Monday ends at the start of Tuesday. Check the shown date range when planning across daylight-saving changes. Keep private notes and account details out of public copy until you deliberately use them.']},
  {id:'read-status-and-source',title:'Read the source before taking action',paragraphs:[],bullets:['A manual plan is your intended work. Marking it done records your own completion decision; it does not verify publication, engagement, a payment or a customer outcome.','A Campaigns item is a reminder to publish manually. It keeps the selected Planning account and reminder time zone. Unassigned reminders stay under No account; choose a profile in Campaigns to include one in that account’s schedule. Even an email asset with a publishing reminder is not an enrolled email delivery job.','An Emails item reflects an actual queued job or recorded provider acceptance. Its due time is the earliest scheduled dispatch or retry opportunity, not a promise of inbox delivery. Paused and failed states still need attention in Emails.','A service booking comes from the selected test or live payment mode and its booking record. Keep cancelled sessions distinct from confirmed ones. A calendar plan is never a confirmed client booking.','A community event is a definition from the current published community configuration. It does not prove attendance or delivery, and existing members may retain the event details in their purchased snapshot.'],note:'Imported items are read-only here. Use Open source to inspect or change the original campaign, sequence, customer record or published community configuration.'},
  {id:'change-and-review',title:'Change plans without changing delivery',paragraphs:['Edit, mark done, cancel or restore a manual calendar item as your plan changes. Cancelling a plan retains its record. It does not cancel a client booking, pause an email sequence, refund a purchase or remove content from a social platform. Use Show cancelled when you need to find a retained plan.','Scheduling from Funnel Builder keeps a reference to the source idea or step. It creates a private plan only; the actual recording, copy review, destination and manual publication still need to happen. Use measured Results and the original delivery history to judge what happened after executing the plan.'],links:[{label:'Schedule an idea from Funnel Builder',href:'/docs/marketing/funnel-builder'},{label:'Understand campaigns and email delivery',href:'/docs/marketing/campaigns-and-emails'},{label:'Review service bookings',href:'/docs/create/services'}]}
 ]},
 {slug:'create/choose-a-format',group:'Create your product',title:'Choose a product format',description:'Match the structure to the customer’s real outcome.',minutes:5,tags:['book','guide','course','coaching','consulting','community','formats','designs','printables'],sections:[
  {id:'choose-by-delivery',title:'Choose by what the buyer receives',paragraphs:['A format sets up a suitable authoring and delivery structure. Start with the simplest format that supports the work, rather than choosing a full course for every idea.'],bullets:['Book, guide and playbook: structured written material, processes and original resources.','Designs & printables: editable invitations, colouring books, posters, worksheets and graphics with printable downloads.','Mini course: a focused outcome with a short lesson sequence.','Full / video course: modules, lessons and your recordings.','Template kit: reusable original files with tool compatibility and instructions.','Challenge: a sequence of tasks and completion criteria.','Consulting or coaching: preparation, intake, sessions and service policies.','Community: member onboarding, channels, rules and an ongoing member promise.','Custom: a delivery structure for a product that needs a different combination.']},
  {id:'choose-a-source',title:'Choose how to start',paragraphs:['Manual creation lets you write your own structure. Upload existing content preserves your original material as the starting point. AI can propose structure or copy when enabled, but should not invent your teaching experience or customer results.','For an existing PDF or template, an upload-first product may be enough. For a recorded course, organize the lessons and attach the recordings you want customers to receive.']},
  {id:'set-expectations',title:'Write a concrete promise',paragraphs:['Describe who the product is for, what it includes and the action the customer can take after using it. Keep uncertain results framed as goals, not guarantees.','Use the same facts in your sales page, shared brief and checkout summary. A format is not a substitute for clear scope, refund terms and support expectations.'],links:[{label:'Create a printable in Design Studio',href:'/docs/create/design-studio'},{label:'Build a course',href:'/docs/create/courses'},{label:'Offer coaching or consulting',href:'/docs/create/services'}]}
 ]},
 {slug:'create/design-studio',group:'Create your product',title:'Create designs and printables',description:'Make editable invitations, colouring books and graphics, then download or publish the reviewed design.',minutes:6,tags:['design studio','designs','printables','invitation','colouring book','poster','worksheet','canvas','SVG','PNG','GPT Image 2','gpt-image-2','image quality'],sections:[
  {id:'open-and-start',title:'Start with a template or a blank page',paragraphs:['Open Design in the workspace navigation and choose New design, or choose Designs & printables from the product format choices. Create the private product to open Design Studio. Choose an invitation, colouring book, poster, worksheet or social template, or begin with a blank page. Templates contain separate editable layers.','Templates and manual editing do not use AI credits. Focus editor gives the canvas more room; Back to product returns to the surrounding product workspace. Use Save design and wait for the saved confirmation before leaving. Neither focusing the editor nor saving publishes your work.']},
  {id:'edit-your-pages',title:'Edit each layer and build multiple pages',paragraphs:['Double-click text to write, then change its font, size, alignment or colour in Properties. Add rectangles, circles and vector shapes, or use Draw by hand; each completed stroke becomes its own drawing layer. Upload a PNG, JPEG or WebP image up to 8 MB to place your own artwork.','Drag layers to move them and use the corner handle to resize. Properties includes position, rotation, opacity, fill and outline controls. Layers lets you reorder the artwork; lock a layer to protect it while editing others. Use Shift-click for multiple selection, arrow keys to nudge, and Undo or Redo to recover a change.','Pages lets you add, duplicate, rename and remove pages, up to 20 pages per design. Set the page size and background in Page settings. Check every page before exporting, including text that may extend beyond its box or the page edge.']},
  {id:'create-with-gen',title:'Create editable text and vector pages',paragraphs:['Gen is optional. In Editable pages mode, choose the design type, describe the artwork and wording, and select how many pages to create. Read the current credit price on Generate design before starting; this mode uses the available text AI service.','Your current work is saved first. A successful result opens for review: choose whether to add its pages or use it as the design. Your current pages stay until you apply the proposal, and Undo can restore a replacement. Credits pay for the completed proposal even if you decide to keep your current design.','Editable pages creates native text and vector layers that you can rewrite, recolour and rearrange. Review names, dates, language and artwork before applying. Templates and manual editing remain available when AI is unavailable.']},
  {id:'generate-image-layer',title:'Generate artwork with GPT Image 2',paragraphs:['Choose Image layer in the Gen panel to use GPT Image 2, model gpt-image-2. Describe the artwork, select square, portrait or landscape size, and choose a transparent or opaque background. The Low, Med and High quality controls sit beside the artwork submit button. Standard prices are 4 credits for Low, 12 for Med and 40 for High; review the selected price shown below the controls before choosing Generate artwork. An unlimited account may show 0 credits. Changing quality does not start generation.','Your current design is saved before generation. The result opens in a private preview. Review it, then choose Add to page to place it on the current page, or Keep current design to dismiss it. A completed image uses the displayed credits even if you decide to keep your current design. Adding the image does not publish your product.','Generated artwork is one raster image layer made of pixels. You can move, resize, rotate and change the opacity of that layer; words and shapes inside the image are not native editable objects. Add your own text and shapes as separate layers when they need to remain editable. Image quality does not turn raster artwork into vectors.']},
  {id:'download-your-design',title:'Choose the right download',paragraphs:['Use the Design Studio Download menu. PDF, PNG, SVG and ZIP save the current design first; Editable FiveGen file also includes your current unsaved edits.'],bullets:['PDF contains all pages at the chosen page size, preserving vector artwork and embedded fonts and including image layers. Print at actual size and review printer margins; add bleed yourself when needed. Unsupported characters may need replacing before PDF export.','PNG is a raster image of the current page. SVG preserves the page’s vector layers and embeds its fonts and images; raster artwork keeps its original pixel resolution.','Editable FiveGen file downloads the layer data as .fivegen.json. Open design reads this format; it does not turn arbitrary PDFs, SVGs or other design files into editable FiveGen layers.','ZIP contains every page as SVG, the complete printable PDF, the editable JSON and any included raster image assets.']},
  {id:'move-and-deliver',title:'Keep image references and customer delivery clear',paragraphs:['A FiveGen JSON file stores image upload references, not the image bytes. Vector-only designs can move between products. A design with images can reopen when those completed uploads still belong to the same product; opening its JSON in another product does not transfer them. The ZIP keeps image files for your archive, but is not a one-click cross-product image import.','To sell the design, return to the product, complete its details and terms, then follow Launch review and the separate publication and Price & access steps. Eligible customers receive the printable PDF and editable design package from their protected purchase area. Downloads use the purchased delivery snapshot; editing or saving today’s draft does not replace an earlier customer’s purchased version.'],links:[{label:'Review launch and publication',href:'/docs/sell/launch-review'},{label:'Understand buyer access',href:'/docs/buyers/purchases'}]}
 ]},
 {slug:'create/courses',group:'Create your product',title:'Create a course and first lesson',description:'Build a curriculum around your own teaching, recordings and practical next actions.',minutes:6,tags:['course','lesson','module','video','assignment','quiz'],sections:[
  {id:'one-useful-lesson',title:'Begin with one useful lesson',paragraphs:['Choose Mini course or Full / video course. The builder opens directly in Curriculum, where Upload recording, Write a lesson and Add a resource are the starting choices. You do not need to complete design or payment settings before adding useful teaching. Give the first lesson a specific title and explain one action the learner can complete. A useful written lesson can stand on its own before you record video.'],steps:['Choose Upload recording for an original MP4 or WebM, Write a lesson for your own text, or Add a resource for a supporting file.','For a written lesson, name the useful result and teach the first step with a concrete example.','Add a small practice action if it helps. A module name is optional.','Save the written lesson privately before attaching a recording to it; switching methods keeps unsaved teaching in place.','Complete the product’s name, audience and Outcome in Product details, then use View as member to inspect delivery. Saving does not publish the course or open checkout.']},
  {id:'organize-the-curriculum',title:'Organize modules and lessons',paragraphs:['For a full course, use modules to group related lessons. Reorder lessons so prerequisite work comes before more advanced material. Check that titles tell learners what they will practice instead of listing vague chapter names.','The public curriculum shows an outline. Paid lesson bodies, files and recordings belong in protected delivery; adding a title to a sales page does not expose the full lesson.']},
  {id:'recordings-and-resources',title:'Use your recordings and resources',paragraphs:['Upload the lesson recording through its recording control. The lesson uploader accepts MP4 and WebM and currently shows a 100 MB limit; split larger lessons where needed. The sales-page introduction uses a different uploader with its own limit.','Add captions, transcripts, chapter markers or resources where the lesson supports them. Previewing draft text as the owner does not verify protected video playback for a real customer.']},
  {id:'advanced-learning',title:'Add assessment only when it helps',paragraphs:['Quiz, assignment, release and prerequisite controls support deeper learning flows. Use them for a clear teaching reason, then inspect how the learner understands locked lessons and completion requirements.','The owner simulation may unlock lessons for inspection. Before launch, test the intended release rules and media permissions with an authorized test buyer.'],links:[{label:'Uploads and recovery',href:'/docs/create/files-and-recordings'},{label:'Understand buyer access',href:'/docs/buyers/purchases'}]}
 ]},
 {slug:'create/files-and-recordings',group:'Create your product',title:'Upload files and recordings',description:'Keep original resources private, attach the right files and recover interrupted uploads.',minutes:5,tags:['upload','files','pdf','video','image','retry'],sections:[
  {id:'choose-the-right-uploader',title:'Choose the right destination',paragraphs:['A product resource, a public sales-page image and a private Creator Library recording have different purposes. Upload into the area where you intend to use the file. Private voice-source recordings are not automatically eligible as public sales media.'],bullets:['Files & resources attaches original material to the product draft.','Lesson recording belongs to a specific lesson.','Sales page image belongs to a public page draft and accepts JPEG, PNG or WebP up to 10 MB.','Sales-page recording accepts MP4 or WebM up to 1 GB.','Creator Library source material stays private and is reviewed separately for AI context.']},
  {id:'upload-and-attach',title:'Upload, attach and save',paragraphs:['Read the accepted formats and size limit beside the control before selecting a file. Wait for upload completion, then confirm the file appears in the intended draft.','Storage and attachment are separate operations. If a file uploaded but the draft could not save, use the previously uploaded file recovery option rather than uploading the same original repeatedly.']},
  {id:'when-upload-fails',title:'Recover an interrupted upload',paragraphs:['Keep the original file. If the upload fails, check the current control’s limit, file type and connection, then retry from that control. A renamed file does not change its real type.','Detach removes a draft attachment; it is not the same as deleting all stored copies or revoking every historical customer entitlement. Read the confirmation for the exact scope of any removal.'],note:'Do not publish private customer information or copyrighted material you do not have permission to distribute.'},
  {id:'test-delivery',title:'Check the customer route',paragraphs:['Use the member preview to inspect the resource placement. A real buyer test must separately confirm that an entitled buyer can open the file and a signed-out visitor cannot open protected content. Public page publication should expose only the media explicitly selected for that page.'],links:[{label:'Design a sales page',href:'/docs/pages/design'},{label:'Review your launch',href:'/docs/sell/launch-review'}]}
 ]},
 {slug:'create/services',group:'Create your product',title:'Offer coaching or consulting',description:'Define scope, preparation, applications and sessions without confusing leads with clients.',minutes:6,tags:['mentorship','coaching','consulting','booking','intake','calendar'],sections:[
  {id:'define-the-service',title:'Define what a client receives',paragraphs:['Choose Coaching or Consulting. State the scope, number of sessions, duration, time zone and preparation. Make the boundaries of support and asynchronous communication explicit.','Add your cancellation policy and service agreement before selling. A marketing promise should match what the client space and your delivery process can support.']},
  {id:'application-or-purchase',title:'Choose an application or direct purchase',paragraphs:['An application collects qualification answers for your review. It does not take payment, grant access or reserve a call. A paid service purchase follows the configured offer and access flow.','Use an application page when you need to decide fit first. Tell applicants what happens next and how you will contact them. Do not describe submission as a confirmed booking.']},
  {id:'booking-and-providers',title:'Review booking and provider readiness',paragraphs:['Set the available service information and inspect the client view. Calendar or meeting connections may depend on platform configuration and your authorized provider account. A saved meeting preference is not proof that a calendar event or meeting was created.','When using a manual meeting link, keep it accurate and accessible only to the intended clients. Check buffers, remaining session counts and cancellation rules in a real authorized test.']},
  {id:'service-notices',title:'Approve confirmations for real service events',paragraphs:['In Emails, prepare and activate the application, booking or cancellation notice for this product. Each is one approved transactional email for a future event, with a delay of no more than 24 hours. Sending still depends on platform email and worker readiness.','An application notice confirms receipt only. A booking notice requires a real live paid booking or rescheduled session and rechecks the current time before sending. Cancellation notices require an actually cancelled session or provider-verified ended subscription; scheduling a later subscription cancellation is not an ended-membership event.','These notices do not accept applicants, charge customers, grant access or confirm refunds. They do not create marketing consent. If a session changes again, an outdated booking confirmation is stopped. Earlier events are not enrolled when you activate a template, and unsent service notices expire after seven days.'],links:[{label:'Review email audiences and approval',href:'/docs/marketing/campaigns-and-emails'}]},
  {id:'intake-and-follow-up',title:'Keep intake and marketing permission separate',paragraphs:['Ask only for preparation you need to deliver the service. Applying for help or buying a session does not automatically mean someone opted into every sales sequence.','Use Customers to review applications and relevant notes. Keep private client details out of public testimonials and Creator Library source material unless you have suitable permission.'],links:[{label:'Create an application page',href:'/docs/pages/lead-and-application-pages'},{label:'Customers and relationships',href:'/docs/customers/people'}]}
 ]},
 {slug:'create/community',group:'Create your product',title:'Set up a community',description:'Give members a clear welcome, useful channels and honest access terms.',minutes:5,tags:['community','membership','tiers','channels','events','moderation'],sections:[
  {id:'member-promise',title:'Start with a member promise',paragraphs:['Define who the community is for and why members return. Add a welcome, rules and a small number of useful channels before creating complex activity loops.','Keep the first action obvious: introduce yourself, read a resource or join a planned discussion. An empty community should explain the next step without invented member activity.']},
  {id:'tiers-and-inclusions',title:'Review tiers and inclusions',paragraphs:['If you use membership tiers, name each plan and describe what it includes. Free, monthly, annual and one-time options must have clear amounts and renewal terms.','Check the public starting price and the exact selected tier at checkout. Access is determined by the purchased plan and retained purchase records, not by a creator changing a label in the page editor.']},
  {id:'onboarding-and-events',title:'Prepare onboarding and events',paragraphs:['Use onboarding steps to connect the member promise to practical actions. Add event details with accurate time zones and destinations. A displayed event is not the same as an automatically created meeting provider session.','Review profile sharing, member posting and moderation permissions. Only collect or expose member information that supports the community experience.']},
  {id:'preview-and-test',title:'Preview without inventing activity',paragraphs:['View as member uses the actual member-space renderer with sample access where supported. It does not create real posts, members, notifications or purchases.','Use authorized buyer testing for rule acceptance, tier permissions and moderation before describing the community as operationally verified.'],links:[{label:'Pricing and renewal terms',href:'/docs/sell/pricing'},{label:'Buyer purchases and access',href:'/docs/buyers/purchases'}]}
 ]},
 {slug:'pages/design',group:'Pages & selling',title:'Design and customize a sales page',description:'Choose a template, edit sections and preview a readable page on desktop and phone.',minutes:6,tags:['sales page','landing page','templates','brand','customize','FAQ','reviews'],sections:[
  {id:'template-and-copy',title:'Choose a starting point',paragraphs:['Open Sales page and choose a template. Cinematic, Essential, Editorial, Personal and Community provide different visual starting points. Changing a template preserves your words, sections and selected uploads.','Edit the hero headline and description around one concrete customer outcome. Keep the primary call to action aligned with checkout, an external destination or the form on this page.']},
  {id:'edit-sections',title:'Edit the page section by section',paragraphs:['Use Page sections to select, add, hide or reorder sections. Benefits, curriculum, creator identity, reviews, FAQ, text, images, recordings and forms can be combined to suit the offer.','Use the adjustable editor width for writing. Full-width page preview gives the design more room and returns to the same selected section and scroll position. Desktop and Mobile switch the preview canvas size.']},
  {id:'identity-and-proof',title:'Know where public information lives',paragraphs:['Page FAQ and public creator identity belong to the selected page. Checkout FAQ, policies and creator-written testimonials are managed separately in Price & access. Account profile and seller payment details have their own ownership.','Verified customer reviews come from eligible customers and can be shared across a product’s pages. A page can control their heading and visibility; it cannot rewrite customer feedback. Empty public review sections remain hidden.'],note:'Do not paste invented ratings or present creator-written testimonials as verified customer reviews.'},
  {id:'save-preview-publish',title:'Save, preview, then publish',paragraphs:['Draft saved means the page draft reached the server. Your public page stays unchanged until you publish page changes. History restores this page’s copy and appearance into a draft; it does not restore product content, payment settings or customer reviews.','Check contrast, long titles, images, form labels and phone layout before publication. Publishing a page does not start checkout or change what existing customers can access.'],links:[{label:'Lead and application pages',href:'/docs/pages/lead-and-application-pages'},{label:'Launch review',href:'/docs/sell/launch-review'}]}
 ]},
 {slug:'pages/lead-and-application-pages',group:'Pages & selling',title:'Create lead and application pages',description:'Give each campaign a focused destination while keeping the main sales page separate.',minutes:5,tags:['lead capture','funnel','form','application','consent','waitlist'],sections:[
  {id:'pick-a-job',title:'Choose the destination’s job',paragraphs:['The main sales page explains the offer. A lead page collects interest or delivers a next-step invitation. An application page collects qualification information for your review. You can create focused pages without rebuilding the main sales page.','Use Lead capture in Marketing when the goal is signups or applications. Choose the page that matches the promise in your campaign.']},
  {id:'create-the-page',title:'Create a private page draft',paragraphs:[],steps:['Choose a lead or application page in the page manager.','Write a clear reason to complete the form and an accurate thank-you message.','Set the form fields or application questions.','Preview the page and its destination.','Publish only when the page and follow-up process are ready.']},
  {id:'consent-and-application-boundaries',title:'Explain what the form does',paragraphs:['Marketing consent is optional and starts unchecked on lead forms. Submitting contact details for a request is different from consenting to an ongoing marketing sequence.','Applications require an explanation of review and the next step. Submission does not book a call, take payment or grant access. Do not send applicants to a purchase or calendar destination that your process cannot support.']},
  {id:'measure-and-follow-up',title:'Connect follow-up and results',paragraphs:['Lead responses appear in Customers. Campaign assets should point to the selected page. Review email readiness before activating automated follow-up, and use approved manual delivery when platform sending is unavailable.','Use Results to inspect the measured journey for the same product and campaign. A signup is interest; it is not a purchase or proof that a buyer will pay.'],links:[{label:'Campaigns and email follow-up',href:'/docs/marketing/campaigns-and-emails'},{label:'Measure useful results',href:'/docs/measure/results'}]}
 ]},
 {slug:'sell/pricing',group:'Pages & selling',title:'Set pricing and access',description:'Make free, one-time and recurring offer terms agree before anyone pays.',minutes:6,tags:['price','subscription','monthly','annual','currency','bundle','payment'],sections:[
  {id:'choose-a-pricing-model',title:'Choose a model that matches delivery',paragraphs:['Open Price & access for the selected product. Set the amount, seller currency and supported pricing model. A one-time purchase, subscription and pay-what-you-want offer make different commitments to the buyer.','An unset or unusable paid price is labeled Price not set in previews and public sales-page rendering; zero is not silently advertised as Free. To offer no-charge access, deliberately choose Free / lead magnet or a free membership tier. For subscriptions, choose the renewal interval and explain how access and cancellation work. For pay-what-you-want, review the minimum and suggested amounts. Do not use an unspecified amount or interval in public copy.']},
  {id:'draft-and-published',title:'Check draft and reviewed terms',paragraphs:['Your saved draft can differ from the currently reviewed commercial offer. Draft previews must identify themselves as drafts; an existing public offer continues to use its published snapshot until the relevant update is reviewed.','Compare the saved setup, page preview and checkout summary. Monthly and yearly amounts must show their interval. A starting price for membership tiers does not describe every plan; the buyer must see the selected plan’s exact terms.']},
  {id:'currencies-and-methods',title:'Describe currencies accurately',paragraphs:['Use a seller currency supported by the configured payment setup. Local payment methods and wallets depend on the provider account, buyer, browser and transaction. A country change does not guarantee that a recurring offer converts automatically into another currency.','Check payment eligibility in the launch diagnostics. Do not advertise Apple Pay, a local currency or another method merely because it appears on a competitor’s checkout.']},
  {id:'bundles-and-access',title:'Review inclusions and policies',paragraphs:['If the offer includes a bundle or membership tier, verify the exact included products and access in the customer snapshot. Clearly explain refund and service policies before purchase.','Changing draft pricing does not by itself change the terms of an earlier customer’s purchase. Test the update path and buyer lifecycle rather than assuming a preview proves billing.'],links:[{label:'Connect seller payments',href:'/docs/sell/connect-payments'},{label:'Launch review',href:'/docs/sell/launch-review'}]}
 ]},
 {slug:'sell/launch-review',group:'Pages & selling',title:'Review and launch your product',description:'Understand content approval, public pages, selling and protected customer delivery.',minutes:6,tags:['publish','launch','readiness','checkout','simulation','test'],sections:[
  {id:'download-without-launch',title:'If you only need a downloadable file',paragraphs:['Open your product and use Preview product, then Download PDF or your chosen format. Downloading your private saved content does not require publishing, a sales page, a price or payment setup.','Choose Set up selling only when you want to accept orders through FiveGen. For publication, preview the saved version and confirm your review once. Individual writing suggestions and private notes are optional.']},
  {id:'four-launch-questions',title:'Answer four launch questions',paragraphs:['A launch is ready when the content, public invitation, checkout and delivery agree. Product Overview explains the next action. Launch review is the separate place to resolve required-content checks, inspect delivery, approve the exact saved version and publish delivery. Price & access owns commercial terms and checkout availability; Sales page owns the public invitation.'],bullets:['Content: is the product useful and approved for the intended audience?','Public page: does the published invitation show the right offer and media?','Checkout: are payment setup, price, currency and renewal terms ready?','Delivery: can an entitled customer reach the correct content or service?']},
  {id:'repair-the-next-blocker',title:'Open the exact repair action',paragraphs:['In Price & access, Before you start selling explains each unmet requirement and gives a repair action. Set price opens the product’s price settings; Finish seller setup opens your account’s payment setup. These are different tasks.','Fix required content opens the first missing content location. Review this version and Review & publish delivery open Launch review. Meeting and availability actions open the relevant service settings. After a repair saves, return to Price & access and recheck what remains. Server checks still run before selling is enabled.'],steps:['Save your current draft.','Resolve required content in Launch review and inspect the delivery preview.','Record editorial approval for the exact saved version, then explicitly publish delivery.','Review price, payments and service availability in Price & access, then explicitly start selling.','Publish the intended Sales page separately and inspect the signed-out buyer route.']},
  {id:'publication-and-selling',title:'Publication and selling are different',paragraphs:['Publishing page changes updates the public design. Publishing or reviewing product delivery sets the content customers receive. Starting or pausing new sales controls checkout availability. These actions have different effects on existing customers.','Read the review summary before updating a live product. Some changes can pause new sales until the offer is reviewed again; do not assume editing a draft immediately changes the public offer.']},
  {id:'owner-simulation',title:'Use simulation for inspection',paragraphs:['The buyer journey check can validate internal relationships and render sample access without charging a card. It does not create a real order, grant access, send email or prove a provider webhook completed.','Use View as member to inspect the delivery interface. Use the page preview to inspect the invitation. Neither replaces a controlled payment test.'],note:'A green internal check is not a completed purchase. Keep simulation and real buyer evidence separate.'},
  {id:'real-buyer-test',title:'Verify a controlled buyer lifecycle',paragraphs:['Use an approved sandbox to test successful and failed checkout, duplicate or delayed payment events, receipts, access, return login, cancellation, refund and access end. Keep live charges separate from test mode.','Before sharing, open the canonical public page as a signed-out visitor. Confirm that public copy is visible while paid lessons and files remain protected.'],links:[{label:'Buyer purchases and access',href:'/docs/buyers/purchases'},{label:'Recover a blocked launch',href:'/docs/help/recovery'}]}
 ]},
 {slug:'sell/connect-payments',group:'Pages & selling',title:'Connect seller payments',description:'Understand Stripe Connect, payment readiness and the difference from your FiveGen subscription.',minutes:5,tags:['stripe','connect','payout','seller','payments','live','test'],sections:[
  {id:'what-connect-does',title:'Connect your seller account',paragraphs:['FiveGen uses Stripe Connect to support many creators selling their own products. Seller onboarding links the appropriate Stripe account and collects the information Stripe requires for that account.','Open Seller payments from your account area. Complete the provider’s onboarding, then return to FiveGen and refresh readiness. Follow the status shown for charges and payouts rather than assuming that starting onboarding completed it.']},
  {id:'different-payment-jobs',title:'Keep three payment jobs separate',paragraphs:['Seller payments supports sales to your customers. Plan billing manages your own FiveGen subscription. Your purchases manages products you bought from creators. Using the same card or email does not make these the same billing relationship.','Provider processing fees and the platform’s plan-based seller fee can affect proceeds. Review the current pricing and earnings summary; use the account’s actual entitlement rather than a manually selected plan name.']},
  {id:'readiness-before-checkout',title:'Read readiness before launch',paragraphs:['A product may still be unable to sell if the platform payment configuration, account capabilities or reviewed offer is incomplete. The recovery route depends on whether the blocker belongs to FiveGen, your seller account or the product.','Test mode and live mode are separate. Test webhooks and test balances do not prove live payments are configured. Never paste secret API or webhook signing keys into a public page, client-side field or support screenshot.']},
  {id:'payment-trouble',title:'If a buyer cannot pay',paragraphs:['Check the offer’s availability, currency and payment readiness first. Capture the visible error, approximate time, product and whether it was test or live. Avoid sharing card numbers or secrets.','A provider-accepted payment needs the corresponding order and access event to reach FiveGen. Do not repeatedly charge the customer to diagnose a delivery issue.'],links:[{label:'Pricing and access',href:'/docs/sell/pricing'},{label:'Troubleshooting and recovery',href:'/docs/help/recovery'}]}
 ]},
 {slug:'marketing/growth-plan',group:'Grow your audience',title:'Build a focused growth plan',description:'Choose the next customer action before choosing more tools.',minutes:5,tags:['marketing','brief','ICP','offer','research','growth'],sections:[
  {id:'start-with-a-goal',title:'Start with the customer’s next step',paragraphs:['Marketing surrounds the product; it does not replace the creator’s teaching. Decide whether the next useful action is learning about the offer, joining a list, applying for help or purchasing.','Marketing is organized into Plan, Create, Follow up and Results. Plan contains Growth plan, Funnel Builder and the relevant research or source tools. Create contains Sales video, Lead capture and Campaigns. Follow up opens Emails. Results explains recorded activity and the next action. Saved tool visibility still determines which optional shortcuts appear. The growth plan connects the relevant destination, campaign assets and follow-up; the product’s Sales page remains its public offer editor.']},
  {id:'use-a-shared-brief',title:'Use a shared brief',paragraphs:['Use Your product brief · reused here to inspect the audience, useful outcome, offer, pain points and creator story across marketing tools. Edit shared product brief opens the common interview and offers a return to the tool you came from. Blank audience, outcome, tone and offer answers can inherit saved Product details; the useful outcome comes from the saved Outcome field, never from a substituted description.','A saved shared answer is an override and is kept when product defaults change. Review the source labels before replacing it. Saving the common brief does not rewrite campaign copy, publish pages, change checkout prices or replace approved email snapshots. Add the creator’s story, audience beliefs and objections only when they help this offer.','Keep unknowns honest. If you have no customer proof, do not fill the gap with invented results. Use a clear explanation, sample or demonstration instead.']},
  {id:'choose-the-right-tool',title:'Choose the tool for the job',paragraphs:[],bullets:['Offer research: clarify the audience and test a hypothesis with a waitlist or survey.','Sales video: write a script around the creator’s expertise and real recording.','Lead capture: create the focused signup or application destination.','Campaigns: coordinate copy, assets and a publishing calendar.','Emails: review delivery rules and activate follow-up only when ready.','Results: inspect measured visits, leads, bookings and purchases.']},
  {id:'review-before-execution',title:'Review before execution',paragraphs:['AI outputs are proposals. Check claims, source permissions, the offer and the destination before applying copy or activating a sequence. A calendar reminder is not automatic social publishing.','Start with one message and one destination. Use the measured response to decide the next experiment instead of adding every available channel at once.'],links:[{label:'Prepare a sales video',href:'/docs/marketing/sales-video'},{label:'Campaigns and emails',href:'/docs/marketing/campaigns-and-emails'}]}
 ]},
 {slug:'marketing/sales-video',group:'Grow your audience',title:'Prepare your sales video',description:'Use the creator’s real expertise to write a script and connect the recording to a page.',minutes:5,tags:['VSL','sales video','script','recording','voice'],sections:[
  {id:'write-for-one-offer',title:'Write for one audience and offer',paragraphs:['A sales video script helps explain the problem, the creator’s approach, the offer and the next action. It is not a substitute for an authentic recording or evidence of the creator’s results.','Review Your product brief · reused here first. Saved product facts and shared overrides show where the audience, outcome, tone and inclusions came from. A blank outcome stays unknown until you supply it; FiveGen does not treat the description as a responsible outcome. Existing shared answers and script drafts are kept until you deliberately edit them. Choose the destination before writing the close: a signup, application and checkout need different calls to action.']},
  {id:'draft-and-review',title:'Draft and review the script',paragraphs:[],steps:['Open Sales video for the selected product.','Use approved creator sources or write your own story and examples.','Draft the structure, objection handling and next step.','Review every public claim and remove anything you cannot support.','Save the approved copy, record it yourself and connect the intended page destination.']},
  {id:'connect-recording',title:'Connect the actual recording',paragraphs:['The sales-page recording section accepts the selected public introduction. A private voice-source recording is not automatically made public; upload or select public sales media deliberately.','Preview the recording placement and the adjacent call to action. A saved script does not prove that a video exists, plays on a phone or is included in the published page.']},
  {id:'keep-versions-clear',title:'Keep versions and follow-up clear',paragraphs:['When the offer or destination changes, review the script again. Use the relevant saved version rather than assuming the latest generated text was approved.','Script saving prepares content. Email activation and social publishing are separate actions; use Campaigns and Emails for the next execution step.'],links:[{label:'Creator voice sources',href:'/docs/marketing/creator-voice'},{label:'Sales-page design',href:'/docs/pages/design'}]}
 ]},
 {slug:'marketing/campaigns-and-emails',group:'Grow your audience',title:'Coordinate campaigns and emails',description:'Move reviewed copy into a delivery rule and track what actually happened.',minutes:7,tags:['campaign','email','automation','sequence','welcome','unsubscribe','publishing'],sections:[
  {id:'prepare-assets',title:'Prepare a coherent campaign',paragraphs:['Campaigns groups messages and assets around one offer and destination. Use a creator recording or approved source to prepare posts, short-video scripts and emails in the same voice.','For each item, choose its Planning account and check the time zone printed beside Publishing reminder. Choose a date, select Reminder set · publish manually, then save the campaign. No account · general reminder is valid for work that is not assigned to a profile. A planning profile does not connect or authorize a social platform.','Use Open shared Calendar to see the same account-wide Calendar filtered to this campaign and product. Account filters keep assigned reminders in the intended schedule; edit the source item in Campaigns. Changing a profile changes the displayed reminder zone while retaining a saved instant, so recheck the local date and time. Reminders do not post content or send email.'],links:[{label:'Organize work in Calendar',href:'/docs/workspace/calendar'}]},
  {id:'email-handoff',title:'Move from copy to follow-up',paragraphs:[],steps:['Review the email’s source, subject, body and claims.','Choose the intended signup, application or offer destination.','Open the email handoff beside the campaign copy.','Choose the trigger and recipient rule, then review the sequence and timing.','Activate only after the exact saved revision and delivery readiness are approved.']},
  {id:'readiness-and-consent',title:'Check sending readiness and consent',paragraphs:['Start with the sequence’s plain-language journey and email drafts. Open Sender, page & activation checklist when you are ready to configure the sender, reply-to, postal address and intended page. That setup stays in one disclosure instead of competing with the copy editor. The review step opens the relevant setup when it is incomplete.','Automated email needs platform sending configuration and a valid sender. If FiveGen shows a platform blocker, keep preparing drafts or use an approved manual export; editing copy does not repair provider setup.','Sales follow-up depends on explicit marketing consent. Unsubscribes suppress future marketing, and a purchase should stop the remaining sales sequence for that product. Purchase onboarding has a different purpose from prospect marketing.']},
  {id:'service-event-notices',title:'Use service notices for requested relationships',paragraphs:['Application, booking and cancellation templates are separate from promotional campaigns. Approve a single service email, sender and reply-to for the relevant trigger, then activate the saved revision. Only future matching events enroll; activation does not send to earlier applicants or customers.','Application receipts confirm a submitted request with review consent. Booking confirmations cover actual live paid bookings or rescheduled sessions. Cancellation messages cover a cancelled session or a provider-verified canceled subscription, rather than a merely scheduled subscription cancellation. A current source check stops an obsolete booking message if the time changes, the session is cancelled or paid access ends.','Keep these messages about the request or purchased service. Marketing unsubscribe does not suppress a necessary service confirmation, and receiving a confirmation never opts someone into sales emails. Service notices cannot grant access, confirm acceptance, take payment or promise a refund. They allow at most a 24-hour delay and expire unsent after seven days.'],note:'Test and unpaid booking records cannot trigger live booking confirmations. A configured template does not prove inbox delivery.'},
  {id:'understand-status',title:'Read delivery statuses accurately',paragraphs:['Queued means a job is waiting. Paused means the sequence is not running. Sending can mean provider confirmation is still pending. Accepted by provider means the provider accepted the request; it does not prove the message arrived in an inbox.','Use the message history for a specific recipient and step when diagnosing a failure. Do not retry by repeatedly activating duplicate sequences or importing the same recipient without consent.'],note:'A controlled inbox test is required to verify real delivery. A successful internal simulation is not an email send.'},
  {id:'monitor-and-pause',title:'Monitor and pause deliberately',paragraphs:['Review the recipient rule and current saved revision before activation. Changes may require another approval. Pause the sequence when the offer or recipient expectations change.','Results measures campaign outcomes; the email history explains an individual send. Use the two together instead of treating a drafted email as delivered activity.'],links:[{label:'Map a strategy in Funnel Builder',href:'/docs/marketing/funnel-builder'},{label:'Measure results',href:'/docs/measure/results'},{label:'Customers and relationships',href:'/docs/customers/people'}]}
 ]},
 {slug:'marketing/funnel-builder',group:'Grow your audience',title:'Plan a funnel with Funnel Builder',description:'Map a private customer journey, review its strategy and hand each action to the tool that owns it.',minutes:7,tags:['funnel builder','strategy','journey','graph','marketing','handoff'],sections:[
  {id:'choose-the-right-tool',title:'A strategy, a page and a campaign have different jobs',paragraphs:['Open a product’s Marketing workspace and choose Funnel Builder to work on the strategy around the offer. Its visual plan connects the audience, their next action and the work you need to prepare. The graph is private planning material, not a second sales-page editor.','Sales page owns the public offer and its design. Lead capture owns signup and application forms. Campaigns owns promotional drafts and manual publishing reminders. Emails owns reviewed recipient rules and explicit activation. Growth plan still owns the existing launch checklist and readiness checks.'],note:'A connected box or a saved strategy does not publish a page, start an email sequence, take a payment or grant customer access.'},
  {id:'start-from-real-facts',title:'Start from your actual product',paragraphs:['Begin with the short three-step interview and keep the selected product, audience, outcome and inclusions in view. Distinguish a fact you already saved from a hypothesis you still need to test. Use your real creator experience when answering the interview. This workspace uses those answers and saved product facts; it does not automatically read Creator Library recordings or private customer records.','AI planning is optional and uses the displayed generation price and available account access. Review any proposed journey or copy before applying it. Unknown evidence, customer results and commercial terms should remain unknown rather than becoming invented proof. Your actual teaching stays creator-authored.']},
  {id:'make-the-journey-understandable',title:'Choose one stage and one useful idea',paragraphs:['Use the audience context, then follow Get discovered, Build trust and Invite action. Select a stage to inspect its ideas without opening every checklist at once. Each stage should explain who arrives, what they need to understand and the next realistic action. Keep a simple path before adding branches.','Review each proposed hook, recording outline and call to action in your own voice. Its suggested metric and experiment are hypotheses, not forecasts or live results. Use the map to find missing handoffs. A booking or purchase step must still use the actual product, payment and access rules. An application is a request for review; it is not acceptance or proof of payment. Sales follow-up needs the appropriate recorded marketing permission.']},
  {id:'more-video-ideas',title:'Ask for more video ideas without replacing your work',paragraphs:['Choose More video ideas in the header or beside the idea selector. Select Get discovered, Build trust or Invite action, then add an optional direction such as beginner-friendly tutorials, a personal story, or a question your audience keeps asking. Review the displayed credit price and choose Add 3 ideas.','The new ideas are added to that stage and the first new idea opens automatically. Use Choose a video idea to revisit earlier ideas. Your other stages, custom map, notes and scheduled content stay in place. Each stage holds up to 30 ideas. Replace entire strategy in More options is a separate action that asks before replacing the map.','Use Download outline to save the selected recording plan as a Markdown file. Export plan in More options saves the full current strategy, including unsaved edits. Review the outline in your voice and confirm the intended destination before recording.']},
  {id:'schedule-reviewed-work',title:'Give a reviewed idea a place in your calendar',paragraphs:['When an idea is useful, schedule it with an explicitly selected planning account and date. Check the displayed time zone and product before saving. The calendar item retains its source reference so you can return to the idea or map step. Review the saved calendar item instead of assuming that adding a map connection scheduled anything.','This is a private plan, not a social post or email delivery instruction. No social OAuth connection, posting permission or connected analytics is created by selecting an account profile. Record and prepare the content, then publish manually or use the relevant approved delivery process in its own tool. Marking the plan done records your decision and does not verify publication.'],links:[{label:'Use the global Calendar',href:'/docs/workspace/calendar'}]},
  {id:'save-review-and-handoff',title:'Save strategy, then prepare the actual assets',paragraphs:['Save your private plan and check its save state before switching tools. If saving fails, keep the current plan open and use its retry route. A proposal and an approved published asset are different records.','Use the appropriate contextual handoff to prepare each part in its owning workspace. Review the current public destination in Sales page or Lead capture; review promotional copy in Campaigns; approve recipient rules and activation in Emails. Return to Funnel Builder when the strategy needs to change.'],links:[{label:'Review the growth checklist',href:'/docs/marketing/growth-plan'},{label:'Create a lead or application page',href:'/docs/pages/lead-and-application-pages'},{label:'Prepare campaigns and emails',href:'/docs/marketing/campaigns-and-emails'}]},
  {id:'measure-the-real-work',title:'Measure execution separately from the map',paragraphs:['A plan’s steps and connections do not create visits, contacts, bookings or orders. Use Results for observed page activity, saved requests and verified paid orders. Check page, campaign, payment mode and date scope before drawing a conclusion.','Hiding the Funnel Builder shortcut only changes navigation. It does not remove the saved strategy, unpublish a destination or stop an active sequence. A direct Funnel Builder link still opens its private workspace when the shortcut is hidden.'],links:[{label:'Read actual results',href:'/docs/measure/results'},{label:'Understand save and recovery',href:'/docs/help/recovery'}]}
 ]},
 {slug:'marketing/creator-voice',group:'Grow your audience',title:'Build your Creator Library',description:'Review private sources and choose how each product may use them.',minutes:6,tags:['voice','sources','transcript','authenticity','permission','AI'],sections:[
  {id:'private-source-library',title:'Keep expertise in your own words',paragraphs:['Creator Library stores source material such as your stories, teaching notes, recordings and examples. It helps AI work from the expertise you choose rather than inventing a generic voice.','A saved source is not independent verification of a claim. Include evidence and limits where a result might otherwise sound broader than it is.']},
  {id:'review-and-approve',title:'Review before allowing use',paragraphs:[],steps:['Add your own written material or an eligible recording.','Review and correct the transcript or source text.','Confirm that you own the material or have permission to use it.','Approve the permitted use and relevant limits.','Select the products that may use the approved source.']},
  {id:'profile-vs-product',title:'Separate shared context from product facts',paragraphs:['A creator profile can describe expertise, teaching principles and claim limits across products. Each product separately chooses whether to use it. Product audience, offer and inclusions remain product facts, not automatic permission to use every private source.','Changing or revoking approved source material can invalidate a pending AI suggestion. Review the new source and restart or regenerate the proposal rather than applying an outdated excerpt.']},
  {id:'public-use',title:'Choose what becomes public',paragraphs:['Approving a private source for AI context does not publish the original recording. Generated or suggested public copy should still be reviewed before it is applied.','Do not upload buyer messages, student work or private client information as your own expertise without appropriate permission. Keep original material, AI context and public sales media visibly separate.'],links:[{label:'Prepare a sales video',href:'/docs/marketing/sales-video'},{label:'Campaigns and emails',href:'/docs/marketing/campaigns-and-emails'}]}
 ]},
 {slug:'customers/people',group:'Customers & results',title:'Understand customers and leads',description:'Read the relationship before changing access or following up.',minutes:5,tags:['CRM','customers','lead','application','contact','timeline','consent'],sections:[
  {id:'different-relationships',title:'A person can have several relationships',paragraphs:['A lead expressed interest. An applicant submitted information for review. A buyer has an order and its payment state. A member or client has the access associated with an eligible purchase. These labels should not be treated as interchangeable.','Use the product’s Customers area for a scoped view, or the account-level Customers workspace when you need to understand relationships across products.']},
  {id:'read-a-timeline',title:'Use the relationship timeline',paragraphs:['Open the relevant person and inspect signup, consent, application, booking, order and email events. Follow the linked source record when the detail matters.','A contact note is context for your work; it does not grant protected product access or marketing consent. Do not manually label an unpaid prospect as a paid customer to bypass a payment issue.']},
  {id:'follow-up-safely',title:'Follow up with the right permission',paragraphs:['Review the person’s marketing consent and suppression state before starting sales follow-up. Buying one product does not automatically imply permission for unrelated marketing.','When someone purchases, the prospect sequence for that product should stop and any appropriate onboarding should follow the actual customer state. Inspect the sequence history if the person received the wrong message.']},
  {id:'service-and-support',title:'Use the right service and support record',paragraphs:['Applications help qualify fit; booking and client notes support delivery. Keep sensitive preparation and feedback private.','For a billing or access problem, inspect the order and provider-backed status rather than the contact label alone. The buyer’s own purchases workspace remains the place to reach protected delivery and relevant support.'],links:[{label:'Coordinate campaigns and emails',href:'/docs/marketing/campaigns-and-emails'},{label:'Buyer purchases and access',href:'/docs/buyers/purchases'}]}
 ]},
 {slug:'measure/results',group:'Customers & results',title:'Measure useful results',description:'Read business, product and campaign metrics without overstating what the data proves.',minutes:5,tags:['analytics','dashboard','visits','leads','conversion','earnings','results'],sections:[
  {id:'choose-the-question',title:'Start with a question',paragraphs:['Use Dashboard for business-wide sales, earnings and audience activity. Use product or campaign Results to understand the journey around a specific offer and destination.','The first Results view emphasizes the recorded journey and an explained next action. Choose the question before comparing numbers: are people reaching the page, signing up, applying, booking or purchasing? A single total cannot answer all of these. Open Share-link performance or Business metrics & earnings when you need deeper evidence instead of beginning with every metric at once.']},
  {id:'check-the-scope',title:'Check scope before comparing',paragraphs:['Read the reporting period, time zone and currency. Missing tracking or delayed payment events can affect interpretation. Compare the same product, destination and time window.','Gross sales, platform fees, provider fees and net earnings describe different amounts. A revenue total is not the same as the available seller payout balance.']},
  {id:'read-zero-states',title:'Treat zero as a starting point',paragraphs:['Zero visits may mean you have not shared the page or tracking is not yet present. Zero leads may mean the page’s promise or next step needs work. Zero purchases alone does not identify which problem caused it.','Choose one useful next action: publish the intended page, share one tracked destination, inspect the form or verify checkout readiness. Do not invent a conversion improvement from a tiny or incomplete sample.']},
  {id:'research-vs-buying',title:'Keep research and purchase evidence separate',paragraphs:['Survey responses, waitlist signups and offer preferences are useful interest signals. They are not purchase commitments or proof of willingness to pay the final price.','A campaign draft is not published activity, an email provider acceptance is not inbox delivery, and an owner simulation is not an order. Use the appropriate evidence for each claim.'],links:[{label:'Focused growth plan',href:'/docs/marketing/growth-plan'},{label:'Launch review',href:'/docs/sell/launch-review'}]}
 ]},
 {slug:'buyers/purchases',group:'Customers & results',title:'Find purchases and use your product',description:'Return to purchased content, resume learning and find the right support route.',minutes:5,tags:['buyer','learner','purchases','login','download','support','cancellation'],sections:[
  {id:'return-to-purchases',title:'Return to Your purchases',paragraphs:['Use Your purchases to reach products you bought. Sign in with the account or email associated with the purchase and complete the available verification flow.','The creator dashboard is for making and selling products. You do not need to create a new product to open one you purchased.']},
  {id:'open-the-delivery',title:'Open the product’s customer space',paragraphs:['The product type determines the experience: a classroom for lessons, a reader or downloads for written resources, a client space for services, or the community for an eligible membership.','In a course, use the lesson list or phone selector to continue. Release timing, prerequisites and assignment approval may affect whether the next lesson is available. Read the reason shown for a locked lesson.']},
  {id:'download-and-playback',title:'If a file or recording will not open',paragraphs:['Refresh the purchase status once, then reopen the entitled product. Check your connection and the visible error. A public sales page is not a download link for paid material.','Contact the creator through the product’s support route with the product name and a description of the issue. Do not send full card details or private access tokens.']},
  {id:'billing-and-access',title:'Understand billing and access changes',paragraphs:['Use the purchase’s subscription or billing controls when available to review renewal and cancellation. Your FiveGen creator subscription is a separate relationship.','Cancellation, refunds and access end follow the recorded purchase terms and provider-backed order state. If payment succeeded but access is missing, avoid buying again until the original order is checked.'],links:[{label:'Payment and access recovery',href:'/docs/help/recovery'},{label:'Pricing and renewal terms',href:'/docs/sell/pricing'}]}
 ]},
 {slug:'account/billing-and-credits',group:'Account & integrations',title:'Manage plan billing and AI credits',description:'Keep your platform subscription, AI usage and seller proceeds distinct.',minutes:5,tags:['billing','plan','credits','subscription','AI','cancel','earnings'],sections:[
  {id:'three-balances',title:'Understand the three jobs',paragraphs:['Plan billing manages what you pay FiveGen for your creator plan. AI credits cover eligible generation usage. Seller payments and earnings relate to customer purchases of your products.','A credit top-up is not a product purchase and does not automatically change the seller fee plan. Review the current account pricing screen before buying or changing a plan.']},
  {id:'monthly-allowances',title:'Choose an AI allowance',paragraphs:['Free accounts receive 60 AI credits per UTC calendar month. New Creator Pro subscriptions include 2,000 credits for USD $29 per paid month; Scale includes 6,000 for USD $99. Paid accounts use their subscription allowance instead of the Free credit pool. Existing subscriptions retain the credits promised when purchased, including earlier 2,500-credit Pro subscriptions.','Images cost 4 credits at Low, 12 at Medium, and 40 at High. A balance can be split across quality levels, writing and video. If used only for Medium images, Free can make up to 5, Creator Pro 166, and Scale 500 each month. These are alternative uses of one balance, not separate image allowances.','Free credits reset at 00:00 UTC on the first day of each month. Paid credits reset on the paid monthly anniversary. Neither rolls over; purchased top-ups never expire.']},
  {id:'manual-and-ai',title:'Manual work and AI usage',paragraphs:['Writing your own product and uploading original material do not require FiveGen generation credits. Content written by an assistant through the private MCP save tool also does not spend FiveGen AI credits.','FiveGen AI generation can use an included allowance or credits depending on the account and operation. Check the cost shown before approving generation; different text, image and video operations can have different costs.']},
  {id:'manage-a-subscription',title:'Manage your creator subscription',paragraphs:['Open Plan billing from the account area to inspect the active plan and available billing portal controls. Provider configuration and the actual account entitlement determine what can be changed.','Read the renewal and cancellation terms before confirming a change. Selecting a plan in a local interface does not itself prove that the provider accepted the subscription or updated your entitlement.']},
  {id:'generation-trouble',title:'If generation is unavailable',paragraphs:['Check whether the issue is a balance or allowance limit, an unavailable operation or a platform AI configuration problem. Preserve your draft while diagnosing it.','Retry only after the visible status or balance is understood. If a generation job may still be running, check its status before starting another paid operation. Never paste provider secret keys into the product editor or public support messages.'],links:[{label:'Connect an assistant',href:'/docs/integrations/mcp'},{label:'Troubleshooting and recovery',href:'/docs/help/recovery'}]}
 ]},
 {slug:'integrations/mcp',group:'Account & integrations',title:'Connect an AI assistant with MCP',description:'Authorize a compatible assistant to work on private FiveGen products with explicit permissions.',minutes:6,tags:['MCP','OAuth','Claude','ChatGPT','assistant','connect','API'],sections:[
  {id:'what-the-connection-can-do',title:'What the connection can do',paragraphs:['The FiveGen MCP server lets a compatible assistant read workspace information, create and edit private product content, inspect generation status and manage eligible generated assets.','This is a private creation integration. Its current tool set does not publish public pages, activate seller payments, manage payouts or complete purchases. Review and launch in FiveGen.']},
  {id:'connect',title:'Connect through OAuth',paragraphs:['Open Connect assistant in FiveGen and copy the server URL shown for your workspace. In a compatible client’s remote MCP or custom connector setup, use that URL with OAuth. Menu names and availability differ by client and plan.','Sign in to the same FiveGen account, review the requested permissions and authorize only the access needed. The connection does not require giving the assistant your master provider API keys.'],code:{label:'Production server URL',language:'text',value:'https://www.fivegen.ai/api/mcp'}},
  {id:'permissions',title:'Choose permissions deliberately',paragraphs:[],bullets:['products:read reads private products, assets and workspace usage information.','products:write creates and edits private products and files.','ai:generate permits eligible FiveGen AI operations that may spend credits; write permission is also required for relevant mutations.'],note:'An AI permission does not replace the user’s approval to spend credits. Read the current workspace cost and agree an operation-specific ceiling first.'},
  {id:'use-and-revoke',title:'Start with the workspace and keep control',paragraphs:['Ask the assistant to run get_workspace first. Prefer save_product when you want the assistant itself to author content without a FiveGen AI charge.','Review connected assistants and recent activity in Connect assistant. Disconnect revokes that assistant’s access; it does not delete your saved products. If authorization expires or permissions are missing, reconnect with the intended account and scopes.'],links:[{label:'Tool reference and safe retries',href:'/docs/integrations/mcp-tools'},{label:'Account billing and credits',href:'/docs/account/billing-and-credits'}]}
 ]},
 {slug:'integrations/mcp-tools',group:'Account & integrations',title:'MCP tools and safe retries',description:'Read the current tool contract, prevent stale overwrites and avoid duplicate generation.',minutes:7,tags:['MCP','tools','requestId','expectedUpdatedAt','idempotency','credits','developer'],sections:[
  {id:'read-and-write-tools',title:'Read and write private product content',paragraphs:['get_workspace returns the available balance, costs, AI availability and connection permissions. list_products and get_product read the connected owner’s private products.','create_product creates a manual draft. save_product updates content using the latest expectedUpdatedAt from get_product. Its content object replaces the prior content object, so include every section and file you intend to keep.'],bullets:['get_generation_status reads the current content-generation job.','get_download_links returns signed-in owner download links, not public buyer access links.','list_assets returns asset status; a completed asset is different from a queued job.']},
  {id:'generation-tools',title:'Use paid generation deliberately',paragraphs:['generate_product_step performs one outline, section or launch-kit step. Continue sequentially with a fresh requestId for each new step, and inspect done before claiming completion. stop_generation cancels future content steps while keeping completed work.','revise_product_section asks FiveGen AI to rewrite one section. generate_marketing_asset queues an image or video. sync_marketing_asset checks and saves an existing asset result without starting another generation.','Read live costs through get_workspace rather than hard-coding them. Use confirmSpend and maxCredits for standard paid operations. When the workspace reports unlimited access, the documented tool contract uses maxCredits=0 and confirmSpend=false.']},
  {id:'safe-retries',title:'Retry the same operation safely',paragraphs:['For a retry of the exact same write operation, reuse the same requestId and arguments. A different operation or changed input needs a new requestId. Reusing one ID with different arguments is rejected.','If a request says it is still running or its result is uncertain, read the product or generation status before starting again. A stale expectedUpdatedAt means someone edited the product: read the latest content, preserve intended changes and submit a reviewed update.'],code:{label:'A safe assistant workflow',language:'text',value:'1. get_workspace\n2. create_product with a new requestId\n3. get_product to read current updatedAt\n4. save_product with expectedUpdatedAt and a new requestId\n5. get_product to verify saved content\n6. Review and launch in the FiveGen interface'}},
  {id:'transport-and-auth',title:'Transport and authorization',paragraphs:['The server endpoint uses POST-based Streamable HTTP with OAuth bearer authorization. A plain GET request is not a connectivity test and returns Method Not Allowed. OAuth discovery metadata is available from the configured app origin.','Missing scopes, expired authorization and an incorrect OAuth resource require the appropriate reconnection or configuration fix. Do not put access tokens in URLs, page text or shared screenshots.'],code:{label:'OAuth discovery paths',language:'text',value:'/.well-known/oauth-protected-resource\n/.well-known/oauth-authorization-server'},links:[{label:'Connect with OAuth',href:'/docs/integrations/mcp'},{label:'Recover a failed action',href:'/docs/help/recovery'}]}
 ]},
 {slug:'account/archive-products',group:'Account & integrations',title:'Archive and restore products',description:'Clean up your workspace with a recoverable pause while preserving customer history.',minutes:5,tags:['archive','restore','delete','pause','library','subscription'],sections:[
  {id:'archive-instead-of-delete',title:'Use archive for recoverable cleanup',paragraphs:['Archive takes a product out of circulation without deleting its work, orders or customer history. Use it when an offer is no longer being promoted, when you want to reorganize the library, or when you need a recoverable pause.','Permanent deletion is a separate guarded action. It is not the normal way to hide a product you may need again. Read the effects and current state in the archive dialog before confirming.']},
  {id:'what-archive-changes',title:'Understand the effects before confirming',paragraphs:['Archiving pauses new purchases and makes the product’s public pages private. Marketing sequences pause. Existing orders and eligible customer access remain intact.','Archive does not cancel active subscriptions or erase an earlier purchase’s terms. Transactional service messages and a provider request already in progress can still complete. Use the appropriate subscription, refund or customer controls when that is the actual job.'],note:'Do not use archive as a substitute for canceling a recurring customer subscription.'},
  {id:'archive-and-find',title:'Archive from the product library',paragraphs:[],steps:['Open Products and find the intended product by name.','Open its product actions and choose Archive product.','Review the latest state and the listed effects.','Confirm Archive product when that scope matches your intention.','Use the Archived library filter to find the recoverable product later.']},
  {id:'restore-deliberately',title:'Restore without silently reopening sales',paragraphs:['Open the archived product’s actions and choose Restore to workspace. Restore preserves the saved work and history, but does not republish pages, restart new sales or reactivate email sequences.','Return to Launch review and deliberately reopen only the parts that are ready. A restored product is not automatically a currently available public offer. Archive history records the change for later reference.'],links:[{label:'Review launch readiness',href:'/docs/sell/launch-review'},{label:'Find your way around',href:'/docs/workspace'}]}
 ]},
 {slug:'pages/creator-catalog',group:'Pages & selling',title:'Create a catalog and connect a domain',description:'Give published offers a shared creator home, with explicit domain and HTTPS readiness.',minutes:7,tags:['catalog','storefront','creator','domain','DNS','CNAME','TXT','TLS','website'],sections:[
  {id:'one-home',title:'Give your published offers one home',paragraphs:['Open Brand & catalog in your account area at /account/catalog. Add a title, introduction, creator name and story. Choose a catalog link with 3–50 lowercase letters, numbers or hyphens, starting with a letter.','Choose which of your published product pages to include. Catalog cards use the current public product presentation, never private draft content. An archived or unpublished product disappears from the public catalog automatically.']},
  {id:'identity-and-publication',title:'Review identity, then publish',paragraphs:['Choose the light or dark theme and accent. You can reuse an explicitly published icon from an included product. A public contact email is optional and is never automatically copied from your account email.','Save the catalog draft, inspect the preview, then publish. Saving does not update an existing public catalog. The FiveGen address is /creator/your-link. Making the catalog private does not pause the individual product pages or alter existing purchases.'],note:'A catalog connects offers. Each product keeps its own sales page, checkout, content and customer access settings.'},
  {id:'workspace-address',title:'Choose your workspace address and product paths',paragraphs:['Open Domains below Library in the workspace navigation. Choose an available workspace name and use the FiveGen domain shown in the panel; the platform controls which base domain is configured. Each name belongs to one workspace.','Give each product its own path, such as product1 or product2, without a slash. Choose Save addresses to apply the workspace name and product paths together. Saving addresses does not publish private products. Only current published sales pages can be opened by visitors.','Reserved means the name is saved but FiveGen hosting and HTTPS may still be pending. Wait for Connected before sharing it as a working link. Changing or clearing an existing name or path can break links you already shared.'],links:[{label:'Open Domains',href:'https://www.fivegen.ai/?view=domains'}]},
  {id:'set-up-hostname',title:'Set up a hostname you control',paragraphs:['In Domains, use Connect your own domain. Prefer a new subdomain such as learn.yourdomain.com so you do not disturb an existing website. Enter only the hostname, without https:// or a path, then choose Connect domain.','FiveGen displays an ownership TXT record and the required CNAME. Add the exact records in your DNS provider. Use the current values from your account instead of copying another creator’s verification token. Your product paths can work on this domain once it is connected, without publishing a creator catalog.'],steps:['Add the displayed _fivegen-verification TXT record and exact value.','Point the chosen hostname’s CNAME to the destination shown in FiveGen.','Wait for DNS changes to become visible, then choose Check DNS records.','After both DNS records pass, contact FiveGen support with the hostname for hosting and HTTPS confirmation.']},
  {id:'dns-is-not-hosting',title:'Wait for hosting and HTTPS confirmation',paragraphs:['The domain panel separately tracks ownership, DNS, FiveGen hosting and the HTTPS certificate. Passing DNS checks does not by itself activate routing or issue a certificate. The hostname is ready only when all required states are confirmed.','Replacing a hostname issues a new verification record and resets readiness. Disconnecting keeps your catalog, products and saved FiveGen addresses; remove obsolete records at your DNS provider. Do not remove an existing website’s records unless you intend that change.'],links:[{label:'Manage domains',href:'https://www.fivegen.ai/?view=domains'},{label:'Open catalog settings',href:'https://www.fivegen.ai/account/catalog'},{label:'Design an individual sales page',href:'/docs/pages/design'}]}
 ]},
 {slug:'help/recovery',group:'Account & integrations',title:'Recover a blocked action',description:'Keep your work and find the right recovery path for saves, generation, email, payments and access.',minutes:6,tags:['error','retry','save','conflict','unavailable','support','recovery'],sections:[
  {id:'failed-save',title:'A draft did not save',paragraphs:['Keep the editor open. Read the error and use Retry save after checking the connection. If required fields or URLs are invalid, correct the highlighted setting before retrying.','A newer draft conflict means the server has another saved version. Compare the versions before loading the saved draft or keeping your local draft for a deliberate save. Do not repeatedly overwrite someone else’s work without reviewing the difference.']},
  {id:'generation-or-upload',title:'Generation or upload stopped',paragraphs:['Preserve original files and your current text. Check whether the job is still running before starting another generation. Read the operation’s size, type and credit limits instead of changing unrelated settings.','An upload can finish while the product attachment save fails. Use the available attachment recovery rather than uploading duplicate files. Private source processing does not automatically publish anything.']},
  {id:'email-or-payment',title:'Email or checkout is unavailable',paragraphs:['Read the readiness details to distinguish platform configuration, your account setup and the selected product’s missing steps. A platform sender problem cannot be repaired by rewriting the email.','For checkout, verify selling availability, reviewed amount, currency and seller payment capability. Record the visible error and time, plus test or live mode. Do not expose secret keys or ask a buyer to keep paying to reproduce an access problem.']},
  {id:'buyer-access',title:'A buyer paid but cannot open the product',paragraphs:['Confirm the buyer is using the purchase’s account or verified email. Inspect the original order and provider-backed payment status. Check cancellation, refund or access-end records before changing entitlement.','Owner preview cannot diagnose a real buyer’s permissions because sample access can differ. Use the buyer’s protected route and a controlled authorized test.']},
  {id:'ask-for-help',title:'Send a useful support report',paragraphs:['Include the product name, the action you attempted, approximate time, visible message and whether it happened in test or live mode. A screenshot of the relevant state helps when it contains no secrets or sensitive buyer information.','Keep the original draft and avoid irreversible deletion while the issue is being checked. A recovery route should preserve work and name the next action.'],links:[{label:'Contact FiveGen support',href:'mailto:kamzewac@gmail.com?subject=FiveGen%20support'},{label:'Launch review',href:'/docs/sell/launch-review'}]}
 ]},
];

export function docsHref(slug = '') { return '/docs' + (slug ? '/' + slug : ''); }
export function docsPublicUrl(slug = '') { return 'https://docs.fivegen.ai' + (slug ? '/' + slug : ''); }
export const docsSupportHref='mailto:kamzewac@gmail.com?subject=FiveGen%20support';
export function docsArticle(slug: string) { return docsArticles.find(article => article.slug === slug); }
export function docsText(article: DocsArticle) { return [article.title,article.description,...article.tags,...article.sections.flatMap(section=>[section.title,...section.paragraphs,...section.steps||[],...section.bullets||[],section.note||''])].join(' '); }
export function searchDocs(query:string,limit=8){const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean);return docsArticles.map(article=>{const title=article.title.toLowerCase(),text=docsText(article).toLowerCase();return {article,match:words.every(word=>text.includes(word)),score:words.reduce((score,word)=>score+(title.includes(word)?8:0)+(article.tags.some(tag=>tag.toLowerCase().includes(word))?4:0),0)};}).filter(value=>value.match).sort((a,b)=>b.score-a.score).slice(0,Math.max(1,Math.min(limit,docsArticles.length))).map(value=>value.article);}
export function docsManifest() { return { name:'FiveGen Docs',version:1,canonical:'https://docs.fivegen.ai',groups:[...docsGroups],articles:docsArticles.map(article=>({slug:article.slug,title:article.title,description:article.description,group:article.group,url:'https://docs.fivegen.ai/'+article.slug,path:docsHref(article.slug),sections:article.sections.map(section=>({id:section.id,title:section.title})),text:docsText(article)})) }; }
export function docsLlmsText() { return '# FiveGen\n\n> FiveGen helps creators author, publish and sell digital products, with optional AI growth assistance. These guides describe the current application and its private-creation MCP integration.\n\n## Important boundaries\n\n- Draft saving, sales-page publication, selling and buyer access are separate states.\n- Owner simulations do not charge, create orders, grant access or prove email delivery.\n- MCP currently edits private product content; it does not publish or activate payments.\n- Read get_workspace for current AI costs and permissions. Ask for approved spending limits before paid generation.\n- Never expose private sources, buyer information or credentials.\n\n## Documentation\n\n'+docsArticles.map(article=>`- [${article.title}](https://docs.fivegen.ai/${article.slug}): ${article.description}`).join('\n')+'\n\n## Machine-readable index\n\n- [Documentation manifest](https://docs.fivegen.ai/manifest.json): titles, groups, sections and searchable text from the same source as these guides.\n'; }
